import { InvoiceService } from '../../lib/parcel-kit.js';

export function finishPreauthorizedCheckout(heldAuthorization) {
  return new Promise((resolve, reject) => {
    InvoiceService.capture(heldAuthorization, (failure, receipt) => {
      if (!failure) return resolve(receipt.id);
      InvoiceService.void(heldAuthorization.id, () => reject(failure));
    });
  });
}

after:
import { billing } from '../../lib/parcel-client.js';

export async function finishPreauthorizedCheckout(heldAuthorization) {
  let receipt;
  try {
    receipt = await billing.capture(heldAuthorization);
  } catch (failure) {
    try {
      await billing.void(heldAuthorization.id);
    } catch {
      // Cleanup failure does not replace the capture failure.
    }
    throw failure;
  }
  return receipt.id;
}
